generated_qss:
QMainWindow, QWidget { background-color: #0D1117; color: #E6EDF3; font-size: 10pt; }

QGroupBox {
    border: 1px solid #30363D;
    border-radius: 4px;
    margin-top: 8px;
    padding-top: 0px;
    font-weight: bold;
    color: #00D4FF;
}
QGroupBox::title {
    subcontrol-origin: margin;
    left: 8px;
    padding: 0 4px;
}

QTabWidget::pane
{
    border: 1px solid #30363D;
    top: -1px;
}

QTabBar::tab
{
    background-color: #161B22;
    color: #E6EDF3;
    padding: 6px 12px;
    border: 1px solid #30363D;
    border-top-left-radius: 4px;
    border-top-right-radius: 4px;
    min-width: 70px;
}

QTabBar::tab:selected
{
    background-color: #1C232C;
    color: #00D4FF;
    font-weight: 600;
    margin-bottom: 0px;
}

QTabBar::tab:hover
{
    background-color: #238636;
    color: #FFFFFF;
}

QTabBar::tab:!selected
{
    margin-top: 2px;
}

QListWidget { background-color: #161B22; }
QListWidget::item:selected { background-color: #238636; color: #FFFFFF; }

QTableView {
    background-color: #161B22;
    alternate-background-color: #0D1117;
    color: #E6EDF3;
    gridline-color: #30363D;
    selection-background-color: #1C232C;
}
QHeaderView::section {
    background-color: #1C232C;
    color: #00D4FF;
    border: 1px solid #30363D;
    padding: 3px;
    font-weight: bold;
}
QTableWidget {
    background-color: #161B22;
    color: #E6EDF3;
    gridline-color: #30363D;
}

/* ---- Global input sizing ---------------------------------------------- */
QLineEdit, QComboBox, QSpinBox, QDoubleSpinBox, QDateEdit, QTimeEdit,
QDateTimeEdit, QPlainTextEdit, QAbstractSpinBox {
    background-color: #1C232C;
    color: #E6EDF3;
    border: 1px solid #30363D;
    border-radius: 3px;
    min-height: 28px;
    padding-top: 4px;
    padding-bottom: 4px;
    padding-left: 4px;
    padding-right: 4px;
}
QComboBox QAbstractItemView {
    background: #1C232C;
    color: #E6EDF3;
    selection-background-color: #238636;
    selection-color: #FFFFFF;
}
QComboBox QAbstractItemView::item { min-height: 28px; }
QComboBox::drop-down { border: none; min-height: 28px; }

QTextEdit {
    background-color: #161B22;
    color: #E6EDF3;
    border: 1px solid #30363D;
}

QPushButton {
    background-color: #1C232C;
    color: #E6EDF3;
    border: 1px solid #30363D;
    border-radius: 4px;
    padding: 5px 10px;
}
QPushButton:hover { background-color: #238636; color: #FFFFFF; }
QPushButton:disabled { color: #8B949E; border-color: #30363D; }

/* ---- Named action buttons (set via objectName) ------------------------ */
QPushButton#btnConnect    { background-color: #238636;     color: #0D1117; font-weight: bold; }
QPushButton#btnDisconnect { background-color: #DA3633;  color: #0D1117; }
QPushButton#btnRead       { background-color: #238636;        color: #0D1117; font-weight: bold; }
QPushButton#btnWrite      { background-color: #1F6FEB;       color: #0D1117; font-weight: bold; }
QPushButton#btnWriteRead  { background-color: #8957E5;  color: #0D1117; font-weight: bold; }
QPushButton#btnScan       { background-color: #DB6D28;        color: #0D1117; font-weight: bold; }
QPushButton#btnApply      { font-weight: bold; }
QPushButton#btnSpyStart   { background-color: #238636;     color: #0D1117; font-weight: bold; font-size: 13px; padding: 6px; }
QPushButton#btnSpyStop    { background-color: #DA3633;  color: #0D1117; font-weight: bold; font-size: 13px; padding: 6px; }

QLabel#specgenSectionHeading {
    font-size: 13pt;
    font-weight: 600;
    color: #E6EDF3;
    margin-top: 8px;
    margin-bottom: 4px;
}

QLabel#noteLabel { color: #D29922; font-size: 10px; }
QLabel#mutedLabel { color: #8B949E; }
/* [XREF: file-picker] validated file-status line colors */
QLabel#statusOk { color: #3FB950; }
QLabel#statusError { color: #DA3633; }

QPushButton[saveDirty="true"] {
    background-color: #00D4A0;
    color: #0D1117;
    font-weight: 600;
    border-radius: 3px;
    padding: 4px 12px;
}
QPushButton[saveDirty="true"]:hover { background-color: #00E8B0; }

QStatusBar { background-color: #1C232C; color: #E6EDF3; }
QSplitter::handle { background: #30363D; }
QScrollBar:vertical { background: #0D1117; width: 10px; }
QScrollBar::handle:vertical { background: #30363D; border-radius: 4px; min-height: 20px; }
QCheckBox { color: #E6EDF3; spacing: 5px; }
QRadioButton { color: #E6EDF3; spacing: 6px; }
QProgressDialog { background-color: #0D1117; color: #E6EDF3; }
